// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(uint256 attackerPk, bytes32 guessHash, uint256 lockBlock) public {
        attackerPk = bound(attackerPk, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // Keep the private key in a valid range and derive the attacker address.
        attackerPk = bound(attackerPk, 1, 0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff);
        address attacker = vm.addr(attackerPk);

        // Keep the lock block in a wide, realistic range.
        lockBlock = bound(lockBlock, 1, 100_000_000);

        // Advance to the lock block and fund the attacker for the 1 ether lock-in.
        vm.roll(lockBlock);
        vm.deal(attacker, 1 ether);

        // Attacker locks in a guess at lockBlock; the stored target becomes lockBlock + 1.
        vm.prank(attacker);
        c.lockInGuess{value: 1 ether}(guessHash);

        // This is the block whose hash the reference settles on; the mutant also allows settling.
        vm.roll(lockBlock + 1);

        bool settledSuccessfully = true;
        vm.prank(attacker);
        try c.settle() {
            settledSuccessfully = true;
        } catch {
            settledSuccessfully = false;
        }

        // GENERAL RULE: In the reference, settling at the lock's target block must revert,
        // so no successful settle can occur in that block. The mutant allows it.
        assertTrue(!settledSuccessfully);
    }
}
